using Microsoft.VisualStudio.TestTools.UnitTesting;
using Engine.Models;

namespace TestEngine.Models
{
    [TestClass]
    public class TestPlayer
    {
        [TestMethod]
        public void ConstructorKeepsTheMaximumHitPointsItIsGiven()
        {
            // 250 experience means level 3; that must not overwrite the 100 max hit points.
            Player player = new Player("Test Player", "Fighter",
                experience: 250, maximumHitPoints: 100, currentHitPoints: 75, dexterity: 5, gold: 0);

            Assert.AreEqual(100, player.MaximumHitPoints);
            Assert.AreEqual(75, player.CurrentHitPoints);
            Assert.AreEqual(3, player.Level, "level should still be derived from experience");
        }

        [TestMethod]
        public void ConstructorDoesNotRaiseOnLeveledUp()
        {
            bool leveledUp = false;
            Player player = new Player("Test Player", "Fighter",
                experience: 250, maximumHitPoints: 100, currentHitPoints: 100, dexterity: 5, gold: 0);
            player.OnLeveledUp += (sender, args) => leveledUp = true;

            Assert.IsFalse(leveledUp);
        }

        [TestMethod]
        public void GainingEnoughExperienceLevelsUpAndRaisesTheEvent()
        {
            Player player = new Player("Test Player", "Fighter",
                experience: 0, maximumHitPoints: 10, currentHitPoints: 10, dexterity: 5, gold: 0);
            int levelUps = 0;
            player.OnLeveledUp += (sender, args) => levelUps++;

            player.AddExperience(99);
            Assert.AreEqual(1, player.Level, "99 experience is still level 1");
            Assert.AreEqual(0, levelUps);

            player.AddExperience(1);
            Assert.AreEqual(2, player.Level);
            Assert.AreEqual(20, player.MaximumHitPoints);
            Assert.AreEqual(1, levelUps);
        }

        [TestMethod]
        public void SellingTheEquippedWeaponUnequipsIt()
        {
            Player player = new Player("Test Player", "Fighter",
                experience: 0, maximumHitPoints: 10, currentHitPoints: 10, dexterity: 5, gold: 0);
            player.AddItemToInventory(Engine.Factories.ItemFactory.CreateGameItem(1001));
            GameItem weapon = player.Inventory.Weapons[0];
            player.CurrentWeapon = weapon;

            player.RemoveItemFromInventory(weapon);

            Assert.IsNull(player.CurrentWeapon,
                "the player is still wielding a weapon that left their inventory");
        }
    }
}

